1	package ociresources
2	
3	import (
4		"strings"
5	
6		tea "charm.land/bubbletea/v2"
7	
8		"github.com/anthnel/devdesk/internal/config"
9		"github.com/anthnel/devdesk/internal/docker"
10		"github.com/anthnel/devdesk/internal/ui/keymap"
11	)
12	
13	// InEditMode returns true when a text input is active (blocks command mode).
14	func (b *RegistryBrowser) InEditMode() bool {
15		if b.state == browserStateInput && b.focusedField == brFieldRepo {
16			return true
17		}
18		return b.state == browserStateTags && b.filterActive
19	}
20	
21	// IsSearching returns true while registry tag queries are still in flight.
22	func (b *RegistryBrowser) IsSearching() bool {
23		return b.pendingSearches > 0
24	}
25	
26	// Update handles all messages for the browser.
27	func (b *RegistryBrowser) Update(msg tea.Msg) (*RegistryBrowser, tea.Cmd) {
28		switch msg := msg.(type) {
29		case tea.KeyPressMsg:
30			return b.handleKeyMsg(msg)
31		}
32		return b.delegateUpdate(msg)
33	}
34	
35	func (b *RegistryBrowser) delegateUpdate(msg tea.Msg) (*RegistryBrowser, tea.Cmd) {
36		if b.state == browserStateInput && b.focusedField == brFieldRepo {
37			var cmd tea.Cmd
38			b.repoInput, cmd = b.repoInput.Update(msg)
39			return b, cmd
40		}
41		if b.state == browserStateTags {
42			if b.filterActive {
43				var cmd tea.Cmd
44				b.filterInput, cmd = b.filterInput.Update(msg)
45				b.rebuildTagTable()
46				return b, cmd
47			}
48			return b, b.tagTable.Update(msg)
49		}
50		return b, nil
51	}
52	
53	func (b *RegistryBrowser) handleKeyMsg(msg tea.KeyPressMsg) (*RegistryBrowser, tea.Cmd) {
54		switch b.state {
55		case browserStateInput:
56			return b.handleInputKeyMsg(msg)
57		case browserStateTags:
58			return b.handleTagsKeyMsg(msg)
59		}
60		return b, nil
61	}
62	
63	func (b *RegistryBrowser) handleInputKeyMsg(msg tea.KeyPressMsg) (*RegistryBrowser, tea.Cmd) {
64		switch msg.String() {
65		case "esc":
66			return b, func() tea.Msg { return RegistryBrowserCloseMsg{} }
67		case "down":
68			b.focusedField = min(b.focusedField+1, b.brFieldSubmit())
69			b.updateFocus()
70			return b, nil
71		case "up":
72			b.focusedField = max(b.focusedField-1, brFieldRepo)
73			b.updateFocus()
74			return b, nil
75		case keymap.Space:
76			if b.focusedField >= 1 && b.focusedField <= len(b.rows) {
77				row := b.rows[b.focusedField-1]
78				if row.groupSlug != "" {
79					b.toggleGroup(row.groupSlug)
80					return b, nil
81				}
82				key := b.entries[row.entry].key
83				b.selectedRegs[key] = !b.selectedRegs[key]
84				return b, nil
85			}
86		case "enter":
87			if b.focusedField == brFieldRepo || b.focusedField == b.brFieldSubmit() {
88				return b.submitSearch()
89			}
90			b.focusedField = min(b.focusedField+1, b.brFieldSubmit())
91			b.updateFocus()
92			return b, nil
93		}
94		return b.delegateUpdate(msg)
95	}
96	
97	// credsFor returns the credentials to search entry with, and nothing at all
98	// when the registry — or the group it belongs to — is marked anonymous (D12).
99	// Docker keys credentials by host, so a Nexus instance with one repository
100	// logged into would otherwise send that login to every repository it serves.
101	func (b *RegistryBrowser) credsFor(entry browserRegistryEntry) (string, string) {
102		if !config.UsesCredentials(entry.authMode) {
103			return "", ""
104		}
105		// Credentials come from the parent registry, or the entry itself for a
106		// registry that is not a group member.
107		credURL := entry.URL
108		if entry.parentURL != "" {
109			credURL = entry.parentURL
110		}
111		var username string
112		for _, reg := range b.registries {
113			if reg.URL == credURL {
114				username = reg.Username
115				break
116			}
117		}
118		storedUser, storedPass, _ := docker.GetStoredCreds(credURL)
119		if username == "" {
120			username = storedUser
121		}
122		return username, storedPass
123	}
124	
125	func (b *RegistryBrowser) submitSearch() (*RegistryBrowser, tea.Cmd) {
126		repo := strings.TrimSpace(b.repoInput.Value())
127		if repo == "" {
128			return b, nil
129		}
130	
131		b.tags = nil
132		b.registryFilter = resultFilter{}
133		b.pendingSearches = 0
134		b.filterInput.SetValue("")
135		b.filterActive = false
136		// A new search starts from the default order, not wherever the last one's
137		// `.` presses left the table.
138		b.tagTable.SetSort(tagColumnTag, false)
139	
140		var cmds []tea.Cmd
141		for _, entry := range b.entries {
142			if !b.selected(entry) {
143				continue
144			}
145			username, storedPass := b.credsFor(entry)
146			alias := entry.Alias
147			if entry.ParentAlias != "" {
148				alias = entry.ParentAlias + "/" + entry.Alias
149			}
150			// The prefix is applied here and nowhere else: it is then already part
151			// of MultiRegistryTag.Repo, so multiImageName and registryAPIURL need to
152			// know nothing about it. Teaching both would be two places free to
153			// drift, which is the disagreement D39 already is (§3.18).
154			normalizedRepo := joinRepoPrefix(entry.repoPrefix, normalizeRepoForRegistry(entry.URL, repo))
155			apiURL := registryAPIURL(entry.URL)
156			b.pendingSearches++
157			cmds = append(cmds, searchRegistryTagsCmd(entry.key, entry.URL, alias, apiURL, normalizedRepo, username, storedPass))
158		}
159	
160		if len(cmds) == 0 {
161			return b, nil
162		}
163	
164		b.state = browserStateTags
165		b.tagTable.Focus()
166		b.rebuildTagTable()
167		return b, tea.Batch(cmds...)
168	}
169	
170	func (b *RegistryBrowser) handleTagsKeyMsg(msg tea.KeyPressMsg) (*RegistryBrowser, tea.Cmd) {
171		if b.filterActive {
172			switch msg.String() {
173			case "esc", "enter":
174				b.filterActive = false
175				b.filterInput.Blur()
176				b.rebuildTagTable()
177				b.resizeTagTable()
178				return b, nil
179			}
180			return b.delegateUpdate(msg)
181		}
182	
183		switch msg.String() {
184		case "esc":
185			b.state = browserStateInput
186			b.tagTable.Blur()
187			b.updateFocus()
188			return b, nil
189		case "/":
190			b.filterActive = true
191			b.filterInput.Focus()
192			b.resizeTagTable()
193			return b, nil
194		case "r":
195			b.cycleRegistryFilter()
196			return b, nil
197		case "enter":
198			return b.openTagScanDetails()
199		case keymap.Get:
200			return b.pullSelectedTag()
201		case keymap.Scan:
202			return b.requestDirectScan()
203		}
204		// Navigation and `.` are the table's. `/` never reaches it: the browser's
205		// own filter took the key two cases above, and the table declares no
206		// searchable column, so it would decline it anyway.
207		return b, b.tagTable.Update(msg)
208	}
