15	// openMultiRegistryBrowser opens the multi-registry browser (triggered by 'b' on Images tab).
16	func (m Model) openMultiRegistryBrowser() (tea.Model, tea.Cmd) {
17		if len(m.registries) == 0 {
18			return m, m.footer.Warn("No registries configured — add one in the Registries tab")
19		}
20		// Config plus cache, read here and now: no network, no waiting, no state
21		// that ignores esc (D13).
22		m.registryBrowser = newRegistryBrowser(m.registries, m.groupCache, m.browserDeselected, m.width-2, m.height)
23		m.registryBrowser.SetScanCache(m.scanCache)
24		m.registryBrowser.SetJobs(m.jobs, m.failures, m.contextName)
25		return m, nil
26	}
