28	// closeMultiRegistryBrowser drops the browser, remembering what the user
29	// unchecked so the next visit opens on the same selection.
30	func (m Model) closeMultiRegistryBrowser() (tea.Model, tea.Cmd) {
31		if m.registryBrowser == nil {
32			return m, nil
33		}
34		deselected := m.registryBrowser.Deselected()
35		m.registryBrowser = nil
36	
37		m.browserDeselected = make(map[string]bool, len(deselected))
38		for _, key := range deselected {
39			m.browserDeselected[key] = true
40		}
41		return m, saveBrowserSelectionCmd(deselected)
42	}
