74	// handleRegistryPullRequested admits a browser pull as a job and puts the user
75	// where they can watch it: the Images tab, browser closed (§3.60).
76	//
77	// A pull is asked for from the browser and answered in the Images list, and
78	// leaving the user on the browser's own spinner meant the one screen that could
79	// not show either the progress or the result. The switch happens here, once, on
80	// the keypress that asked for it — it is not a work message dragging the screen
81	// around behind the user's back, which is what D67 forbids.
82	func (m Model) handleRegistryPullRequested(msg RegistryPullRequestedMsg) (tea.Model, tea.Cmd) {
83		if m.pullingImage(msg.ImageName) {
84			return m, m.footer.Warn("Pull already in progress")
85		}
86		start := jobs.Start(m.pullRun(msg.ImageName), pullOneImageCmd(msg.ImageName, m.pullDeps()))
87	
88		// closeMultiRegistryBrowser carries the deselection the next visit reopens
89		// on, so the browser is closed through it rather than by hand.
90		closed, closeCmd := m.closeMultiRegistryBrowser()
91		next, ok := closed.(Model)
92		if !ok {
93			return closed, tea.Batch(closeCmd, start)
94		}
95		next.activeTab = tabImages
96		next.updateImageTable()
97		return next, tea.Batch(closeCmd, start)
98	}
