100	// handleRegistryPullComplete processes the result of a pull.
101	//
102	// It does not depend on the browser any more: the pull outlives it now that
103	// asking for one closes it, and a completion that returned early on a nil
104	// browser would skip the refresh that makes the pulled image appear.
105	func (m Model) handleRegistryPullComplete(msg RegistryPullCompleteMsg) (tea.Model, tea.Cmd) {
106		if msg.Replaces != "" {
107			return m.handleImageUpdated(msg)
108		}
109		if isBlocked(msg.Err) {
110			log.Printf("ERROR [oci_resources] pull %s refused: %v", msg.ImageName, msg.Err)
111			return m, m.footer.Error("Pull of " + msg.ImageName + " refused: " + msg.Err.Error())
112		}
113		if msg.Err != nil {
114			log.Printf("ERROR [oci_resources] pull %s: %v", msg.ImageName, msg.Err)
115			return m, m.footer.Error("Pull failed — check logs")
116		}
117		if msg.Check.Decision == trust.Warn {
118			return m, tea.Batch(fetchImages(), m.footer.Warn("Pulled "+msg.ImageName+" — "+msg.Check.Reason()))
119		}
120		return m, tea.Batch(fetchImages(), m.footer.Info("Image pulled: "+msg.ImageName))
121	}
