150	// handleRegistryGroupDetected records a discovery. Nothing forwards it to the
151	// browser any more: the browser reads the cache when it opens, so a refresh is
152	// something the Registries tab does and the Members column reports.
153	func (m Model) handleRegistryGroupDetected(msg RegistryGroupDetectedMsg) (tea.Model, tea.Cmd) {
154		delete(m.refreshingGroups, msg.Slug)
155	
156		if msg.Err != nil {
157			log.Printf("INFO [oci_resources] group detection failed for %s: %v", msg.RegistryURL, msg.Err)
158			// The cache keeps what was last known rather than being emptied by an
159			// unreachable manager, so the column keeps showing it — stale, and
160			// visibly so.
161			m.updateRegistryTable()
162			return m, m.footer.Error("Group refresh failed — check logs")
163		}
164		if msg.Slug != "" {
165			m.groupCache[msg.Slug] = cache.RegistryGroupEntry{
166				Members:      toCachedMembers(msg.Members),
167				DiscoveredAt: time.Now(),
168			}
169		}
170		m.updateRegistryTable()
171		return m, nil
172	}
