174	// toCachedMembers converts what the detector returned into what the cache and
175	// the table hold.
176	func toCachedMembers(members []registrymgr.GroupMember) []cache.RegistryGroupMember {
177		out := make([]cache.RegistryGroupMember, 0, len(members))
178		for _, m := range members {
179			out = append(out, cache.RegistryGroupMember{Alias: m.Alias, URL: m.URL, RepoPrefix: m.RepoPrefix})
180		}
181		return out
182	}
