184	// handleRegistryGroupCacheLoaded takes the discoveries read from disk.
185	func (m Model) handleRegistryGroupCacheLoaded(msg RegistryGroupCacheLoadedMsg) (tea.Model, tea.Cmd) {
186		if msg.Entries != nil {
187			m.groupCache = msg.Entries
188		}
189		m.updateRegistryTable()
190		return m, nil
191	}
