370	func registryAPIURL(registryURL string) string {
371		base := strings.TrimSuffix(strings.TrimSpace(registryURL), "/")
372		if isDockerHub(base) {
373			return "https://registry-1.docker.io"
374		}
375		lower := strings.ToLower(base)
376		if !strings.HasPrefix(lower, "http://") && !strings.HasPrefix(lower, "https://") {
377			return "https://" + base
378		}
379		return base
380	}
