47	// ActivityTables returns the read-only face of the view's table, keyed by the
48	// name the activity-column guard (internal/app) knows it by. Tests only.
49	func (m Model) ActivityTables() map[string]datatable.ActivityTable {
50		tables := map[string]datatable.ActivityTable{
51			"oci/images":     &m.imageTable,
52			"oci/networks":   &m.networkTable,
53			"oci/volumes":    &m.volumeTable,
54			"oci/registries": &m.registryTable,
55		}
56		// The browser's table is listed open or not, so the guard sees the real one.
57		if m.registryBrowser != nil {
58			tables["oci/registry-browser"] = &m.registryBrowser.tagTable
59		} else {
60			t := newTagTable()
61			t.Resize(m.width, max(m.height, 1))
62			tables["oci/registry-browser"] = t
63		}
64		return tables
65	}
