22	// FilterBarVisible returns true when the filter bar is visible (implements app.FilterBarView).
23	func (m Model) FilterBarVisible() bool {
24		if m.registryBrowser != nil {
25			return m.registryBrowser.FilterIsVisible()
26		}
27		return m.activeTab == tabImages && m.imageTable.FilterBar().IsVisible() &&
28			m.launchForm == nil && m.resourceForm == nil && m.registryForm == nil &&
29			m.networkInspectForm == nil
30	}
31	
32	// modalView renders whichever modal is open, or "" when none is.
33	func (m Model) modalView() string {
34		switch {
35		case m.confirmModal != nil:
36			return m.confirmModal.View()
37		case m.scanAllModal != nil:
38			return m.scanAllModal.View()
39		}
40		return ""
41	}
42	
43	// InEditMode returns true when a form, modal or filter is active
44	func (m Model) InEditMode() bool {
45		return m.launchForm != nil || m.resourceForm != nil || m.registryForm != nil ||
46			m.networkInspectForm != nil ||
47			m.confirmModal != nil || m.scanAllModal != nil ||
48			(m.activeTab == tabImages && m.imageTable.InEditMode()) ||
49			m.registryBrowser != nil
