52	// GetFooterHeight returns the footer height for this view (Rule 124).
53	func (m Model) GetFooterHeight() int {
54		if m.registryBrowser != nil {
55			filterExtra := 0
56			if m.registryBrowser.FilterIsVisible() {
57				filterExtra = 2
58			}
59			return 2 + filterExtra // empty line + info line + optional filter bar
60		}
61		filterExtra := 0
62		if m.activeTab == tabImages {
63			filterExtra = m.imageTable.FilterBar().ExtraHeight()
64		}
65		if m.launchForm == nil && m.resourceForm == nil && m.registryForm == nil &&
66			m.networkInspectForm == nil {
67			crumbExtra := 0
68			if m.registryGroupSlug != "" {
69				crumbExtra = 1 // the drill-down breadcrumb
70			}
71			return 3 + filterExtra + crumbExtra // tab bar + empty line + info line + filter/breadcrumb
72		}
73		return 2 // empty line + info line (no filter bar in form mode)
74	}
75	
76	// formMode reports whether a form or the registry browser has the viewport.
77	func (m Model) formMode() bool {
78		return m.registryBrowser != nil || m.launchForm != nil || m.resourceForm != nil || m.registryForm != nil ||
79			m.networkInspectForm != nil
80	}
