82	// RenderFooter returns the footer content rendered below the viewport (Rule 124).
83	func (m Model) RenderFooter(width int) string {
84		if m.formMode() {
85			// No tab bar or filter bar in form mode — empty line + info line
86			infoLine := m.footer.View(width, m.formStatus())
87			if m.registryBrowser != nil && m.registryBrowser.FilterIsVisible() {
88				return m.registryBrowser.FilterBarView(width) + "\n" + theme.EmptyLineBg(width) + "\n" + infoLine
89			}
90			return theme.EmptyLineBg(width) + "\n" + infoLine
91		}
92		var parts []string
93		if bar := m.imageTable.FilterBar(); m.activeTab == tabImages && bar.IsVisible() {
94			parts = append(parts, bar.View())
95		}
96		if crumb := m.renderRegistryBreadcrumb(width); crumb != "" {
97			parts = append(parts, crumb)
98		}
99		// An error or a notice the user has not read yet comes first: the progress
100		// of what is still running is the least urgent of the three, and the
101		// component is what enforces that order now.
102		parts = append(parts, m.renderTabBar(width), theme.EmptyLineBg(width), m.footer.View(width, m.status()))
103		return strings.Join(parts, "\n")
104	}
