106	// status is what the view derives on every frame: the active tab's load, which
107	// stays first and carries no row detail, then the selected image's own activity
108	// composed with the running action or the batch progress. None has a timer.
109	func (m Model) status() sharedcomponents.Status {
110		if text, ok := m.loadingLabel(); ok {
111			return sharedcomponents.Status{Text: text, Activity: true}
112		}
113		st := sharedcomponents.Status{Text: m.actionLine()}
114		if st.Text == "" {
115			st.Text = sharedcomponents.JobsStatusLine(m.jobs, command.ViewOCIResources)
116		}
117		moving := false
118		if m.activeTab == tabImages {
119			if row, ok := m.imageTable.Selected(); ok {
120				a := m.rowActivity(row)
121				st.Detail = a.Detail
122				moving = a.State == indicator.Running || a.State == indicator.Queued
123			}
124		}
125		if st.Text == "" {
126			st.Text = m.inlineSecretLine()
127		}
128		// Only a detail whose dot moves replaces the dot; a failed row's is fixed.
129		st.Activity = len(jobs.Unfinished(m.jobs)) > 0 && (!moving || st.Detail.IsZero())
130		return st
131	}
