133	// inlineSecretLine says why the selected registry's Logged cell is a warning:
134	// its password sits in the engine's auth file, base64 encoded, which is not
135	// encryption (§3.68). A state rather than a message — it holds for as long as
136	// the row is selected, not for three seconds.
137	func (m Model) inlineSecretLine() string {
138		if m.activeTab != tabRegistries || m.authFile == "" {
139			return ""
140		}
141		url := ""
142		if reg := m.getSelectedRegistry(); reg != nil {
143			url = reg.URL
144		} else if group := m.drilledGroup(); group != nil {
145			url = group.URL
146		}
147		if m.registryLoginStatus[url] != docker.LoginInline {
148			return ""
149		}
150		return "Password stored unencrypted in " + m.authFile + " — configure a credential helper"
151	}
