177	// loadingLabel names what the active tab is fetching, or reports that it is
178	// settled. Only the tab on screen answers: a volumes load says nothing while
179	// the Images tab is showing.
180	func (m Model) loadingLabel() (string, bool) {
181		switch m.activeTab {
182		case tabImages:
183			return "Loading images...", m.loading && len(m.images) == 0
184		case tabNetworks:
185			return "Loading networks...", m.loadingNets && len(m.networkTable.Items()) == 0
186		case tabVolumes:
187			return "Loading volumes...", m.loadingVols && len(m.volumeTable.Items()) == 0
188		}
189		return "", false
190	}
