192	// footerLoading reports whether the footer shows a load of this view's own,
193	// whichever face it renders: the active tab's (table empty only), the
194	// browser's search, or the network inspection. WantsBlink reads it, in the
195	// same priority order as formStatus.
196	func (m Model) footerLoading() bool {
197		if !m.formMode() {
198			_, ok := m.loadingLabel()
199			return ok
200		}
201		if m.registryBrowser != nil {
202			if _, ok := m.registryBrowser.LoadingLabel(); ok {
203				return true
204			}
205		}
206		return m.networkInspectForm != nil && m.networkInspectForm.loading
207	}
