209	// renderRegistryBreadcrumb renders the drill-down trail below the table when
210	// the Registries tab has entered a group (Rules 111, 123). Breadcrumb mode: it
211	// is not navigable, the level you are on is highlighted and the one above is
212	// dimmed. Empty at the top level, where there is no trail to show.
213	func (m Model) renderRegistryBreadcrumb(width int) string {
214		group := m.drilledGroup()
215		if group == nil {
216			return ""
217		}
218		tabs := []theme.TabItem{
219			{Label: "Registries"},
220			{Label: browserAlias(*group)},
221		}
222		return theme.PadWithBg(theme.Bg(" ")+theme.RenderTabs(tabs, 1), width)
223	}
