225	// renderTabBar renders the tab bar below the viewport (Rule 123)
226	func (m Model) renderTabBar(width int) string {
227		tabs := []theme.TabItem{
228			{Label: theme.ContainerEngineIcon(engine.Current().Name) + " Images"},
229			{Label: theme.IconNetwork + " Networks"},
230			{Label: theme.IconVolume + " Volumes"},
231			{Label: theme.IconServer + " Registries"},
232		}
233		return theme.PadWithBg(theme.Bg(" ")+theme.RenderTabs(tabs, int(m.activeTab)), width)
234	}
