236	// GetTitle returns the view title
237	func (m Model) GetTitle() string {
238		base := theme.ContainerEngineIcon(engine.Current().Name) + " OCI Resources"
239		if m.registryBrowser != nil {
240			title := base + " " + theme.IconChevronRight + " Registry Browser"
241			if m.registryBrowser.state == browserStateTags && m.registryBrowser.repoInput.Value() != "" {
242				title += " " + theme.IconChevronRight + " " + m.registryBrowser.repoInput.Value()
243			}
244			if !m.registryBrowser.registryFilter.isEmpty() {
245				title += " [" + m.registryBrowser.registryFilterLabel() + "]"
246			}
247			return title
248		}
249		if m.launchForm != nil {
250			return base + " " + theme.IconChevronRight + " Launch Container"
251		}
252		if m.resourceForm != nil {
253			return base + " " + theme.IconChevronRight + " " + m.resourceForm.GetTitle()
254		}
255		if m.registryForm != nil {
256			return base + " " + theme.IconChevronRight + " " + m.registryForm.GetTitle()
257		}
258		if m.networkInspectForm != nil {
259			return base + " " + theme.IconChevronRight + " Network Inspect"
260		}
261		return base
262	}
