269	// GetHeaderInfo returns the key-value info for the header
270	func (m Model) GetHeaderInfo(_ string) []shortcut.HeaderInfo {
271		if m.registryBrowser != nil && m.registryBrowser.state == browserStateTags {
272			return []shortcut.HeaderInfo{
273				{Key: "Tags", Value: fmt.Sprintf("%d", len(m.registryBrowser.tagTable.Items())), Style: theme.HeaderValueStyle},
274			}
275		}
276		if m.networkInspectForm != nil {
277			return []shortcut.HeaderInfo{
278				{Key: "Containers", Value: fmt.Sprintf("%d", len(m.networkInspectForm.containers)), Style: theme.HeaderValueStyle},
279			}
280		}
281		switch m.activeTab {
282		case tabNetworks:
283			return []shortcut.HeaderInfo{
284				{Key: "Networks", Value: fmt.Sprintf("%d", len(m.networkTable.Items())), Style: theme.HeaderValueStyle},
285			}
286		case tabVolumes:
287			return []shortcut.HeaderInfo{
288				{Key: "Volumes", Value: fmt.Sprintf("%d", len(m.volumeTable.Items())), Style: theme.HeaderValueStyle},
289			}
290		case tabRegistries:
291			return []shortcut.HeaderInfo{
292				{Key: "Registries", Value: fmt.Sprintf("%d", len(m.registries)), Style: theme.HeaderValueStyle},
293			}
294		default:
295			visible := m.imageTable.Visible()
296			total := len(visible)
297			var totalDisk int64
298			for _, row := range visible {
299				totalDisk += row.Image.UniqueSize
300			}
301			infos := []shortcut.HeaderInfo{
302				{Key: "Images", Value: fmt.Sprintf("%d", total), Style: theme.HeaderValueStyle},
303				{Key: "Disk Usage", Value: formatBytes(totalDisk), Style: theme.HeaderValueStyle},
304			}
305			unscanned := m.unscannedCount()
306			if unscanned > 0 {
307				infos = append(infos, shortcut.HeaderInfo{
308					Key:   "Unscanned",
309					Value: fmt.Sprintf("%d", unscanned),
310					Style: lipgloss.NewStyle().Foreground(theme.ColorHighlight).Background(theme.ColorBackground),
311				})
312			}
313			if sig, ok := m.signatureHeader(); ok {
314				infos = append(infos, sig)
315			}
316			return infos
317		}
318	}
319	
320	// GetShortcuts returns the keyboard shortcuts for the header (Rule 130: dynamic shortcuts)
321	func (m Model) GetShortcuts() shortcut.Shortcuts {
322		if m.registryBrowser != nil {
323			switch m.registryBrowser.state {
324			case browserStateTags:
325				if m.registryBrowser.filterActive {
326					return []shortcut.Shortcut{
327						{Key: "enter/esc", Description: "Close filter"},
328					}
329				}
330				// enter is greyed on a tag nothing has scanned yet, rather than
331				// appearing and disappearing as the cursor runs down the list
332				// (Rule 130).
333				return []shortcut.Shortcut{
334					{Key: "enter", Description: "View CVE details",
335						Disabled: !m.registryBrowser.HasSelectedTagScanResults()},
336					{Key: keymap.Scan, Description: "Scan image"},
337					{Key: keymap.Get, Description: "Pull image"},
338					{Key: "r", Description: "Filter registry"},
339					{Key: "/", Description: "Filter"},
340					{Key: ".", Description: "Sort"},
341					{Key: "esc", Description: "Go back"},
342				}
343			default: // browserStateInput
344				// enter submits, so it is greyed until the submit button has the
345				// focus. A control, not an action: greying is the whole of it, and
346				// a footer line on every stray enter in a form would be noise.
347				return []shortcut.Shortcut{
348					{Key: "enter", Description: "Browse tags",
349						Disabled: m.registryBrowser.focusedField != m.registryBrowser.brFieldSubmit()},
350					{Key: "esc", Description: "Close browser"},
351				}
352			}
353		}
354		if m.launchForm != nil {
355			lf := m.launchForm
356			isCheckbox := lf.isPortField(lf.focusedField) ||
357				lf.focusedField == lf.fieldOptionRemove() ||
358				lf.focusedField == lf.fieldOptionDetach() ||
359				lf.focusedField == lf.fieldOptionInteractive()
360			// The three controls a field can take, greyed rather than swapped: the
361			// column changed shape on every ↑↓, in a form where the cursor moves
362			// constantly (Rule 130).
363			return []shortcut.Shortcut{
364				{Key: "space", Description: "Toggle", Disabled: !isCheckbox},
365				{Key: "←→", Description: "Cycle network", Disabled: lf.focusedField != lf.fieldNetwork()},
366				{Key: "enter", Description: "Launch", Disabled: lf.focusedField != lf.fieldSubmit()},
367				{Key: "ctrl+y", Description: "Copy command"},
368				{Key: "esc", Description: "Cancel"},
369			}
370		}
371		if m.resourceForm != nil {
372			// Only a network has a driver to cycle, and only on its second field.
373			onDriver := m.resourceForm.kind == resourceFormNetwork && m.resourceForm.focusedField == 1
